draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // drawing a stick figure with pulsing size
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  // drawing arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 20 - 10 * Math.sin(t));
  ctx.lineTo(W/2 - 30 - 10 * Math.cos(t), H/2 + 20);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 20 - 10 * Math.sin(t));
  ctx.lineTo(W/2 + 30 + 10 * Math.cos(t), H/2 + 20);
  ctx.stroke();

  // drawing legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 + 10 * Math.sin(t));
  ctx.lineTo(W/2 - 30 - 10 * Math.cos(t), H/2 + 60);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 + 10 * Math.sin(t));
  ctx.lineTo(W/2 + 30 + 10 * Math.cos(t), H/2 + 60);
  ctx.stroke();

  // drawing a circle around the figure to represent energy
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.setLineDash([10, 10]);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.restore();
}
